 * Story 10.6: Dashboard 退出策略管理
 */

import { describe, it, expect, vi, beforeEach } from 'vitest';

// Mock the client module
vi.mock('./client', () => ({
  get: vi.fn(),
  put: vi.fn(),
}));

describe('Settings API', () => {
  beforeEach(() => {
    vi.clearAllMocks();
  });

  describe('fetchExitStrategyConfig', () => {
    it('should call the correct endpoint', async () => {
      const mockConfig = {
        auto_exit_enabled: true,
        take_profit_threshold: 0.8,
        stop_loss_threshold: 0.3,
        time_based_exit_hours: 24,
        trailing_stop_percentage: 0.1,
      };

      const mockGet = vi.fn().mockResolvedValue(mockConfig);
      vi.mocked(await import('./client')).get = mockGet;

      const { fetchExitStrategyConfig } = await import('./settings');
      const result = await fetchExitStrategyConfig();

      expect(mockGet).toHaveBeenCalledWith('/api/settings/exit-strategy');
      expect(result.auto_exit_enabled).toBe(true);
      expect(result.take_profit_threshold).toBe(0.8);
    });

    it('should return config with all required fields', async () => {
      const mockConfig = {
        auto_exit_enabled: false,
        take_profit_threshold: 0.75,
        stop_loss_threshold: 0.25,
        time_based_exit_hours: 48,
        trailing_stop_percentage: 0.15,
      };

      const mockGet = vi.fn().mockResolvedValue(mockConfig);
      vi.mocked(await import('./client')).get = mockGet;

      const { fetchExitStrategyConfig } = await import('./settings');
      const result = await fetchExitStrategyConfig();

      expect(result).toHaveProperty('auto_exit_enabled');
      expect(result).toHaveProperty('take_profit_threshold');
      expect(result).toHaveProperty('stop_loss_threshold');
      expect(result).toHaveProperty('time_based_exit_hours');
      expect(result).toHaveProperty('trailing_stop_percentage');
    });
  });

  describe('updateExitStrategyConfig', () => {
    it('should call PUT with correct endpoint and data', async () => {
      const mockUpdatedConfig = {
        auto_exit_enabled: true,
        take_profit_threshold: 0.9,
        stop_loss_threshold: 0.2,
        time_based_exit_hours: 12,
        trailing_stop_percentage: 0.05,
      };

      const mockPut = vi.fn().mockResolvedValue(mockUpdatedConfig);
      vi.mocked(await import('./client')).put = mockPut;

      const { updateExitStrategyConfig } = await import('./settings');
      const updateData = { take_profit_threshold: 0.9 };
      const result = await updateExitStrategyConfig(updateData);

      expect(mockPut).toHaveBeenCalledWith(
        '/api/settings/exit-strategy',
        updateData
      );
      expect(result.take_profit_threshold).toBe(0.9);
    });

    it('should support partial updates', async () => {
      const mockUpdatedConfig = {
        auto_exit_enabled: false,
        take_profit_threshold: 0.8,
        stop_loss_threshold: 0.3,
        time_based_exit_hours: 24,
        trailing_stop_percentage: 0.1,
      };

      const mockPut = vi.fn().mockResolvedValue(mockUpdatedConfig);
      vi.mocked(await import('./client')).put = mockPut;

      const { updateExitStrategyConfig } = await import('./settings');
      const result = await updateExitStrategyConfig({ auto_exit_enabled: false });

      expect(mockPut).toHaveBeenCalledWith(
        '/api/settings/exit-strategy',
        { auto_exit_enabled: false }
      );
      expect(result.auto_exit_enabled).toBe(false);
    });
  });

  describe('settingsApi', () => {
    it('should export settingsApi object with correct methods', async () => {
      const mockConfig = {
        auto_exit_enabled: true,
        take_profit_threshold: 0.8,
        stop_loss_threshold: 0.3,
        time_based_exit_hours: 24,
        trailing_stop_percentage: 0.1,
      };

      const mockGet = vi.fn().mockResolvedValue(mockConfig);
      const mockPut = vi.fn().mockResolvedValue(mockConfig);
      vi.mocked(await import('./client')).get = mockGet;
      vi.mocked(await import('./client')).put = mockPut;

      const { settingsApi } = await import('./settings');

      // Test getExitStrategy
      await settingsApi.getExitStrategy();
      expect(mockGet).toHaveBeenCalledWith('/api/settings/exit-strategy');

      // Test updateExitStrategy
      await settingsApi.updateExitStrategy({ auto_exit_enabled: true });
      expect(mockPut).toHaveBeenCalledWith('/api/settings/exit-strategy', {
        auto_exit_enabled: true,
      });
    });
  });
});

