/**
 * Exit Strategy Settings component tests.
 *
 * Tests for the ExitStrategySettings component.
 *
 * Story 10.6: Dashboard 退出策略管理
 */

import { describe, it, expect, vi, beforeEach } from 'vitest';
import { render, screen, waitFor } from '@testing-library/react';
import userEvent from '@testing-library/user-event';
import { QueryClient, QueryClientProvider } from '@tanstack/react-query';
import type { ReactNode } from 'react';

// Mock the API
vi.mock('@/api/settings', () => ({
  settingsApi: {
    getExitStrategy: vi.fn(),
    updateExitStrategy: vi.fn(),
  },
}));

// Mock useToast
vi.mock('@/hooks/use-toast', () => ({
  useToast: () => ({
    toast: vi.fn(),
  }),
}));

const createWrapper = () => {
  const queryClient = new QueryClient({
    defaultOptions: {
      queries: {
        retry: false,
      },
    },
  });

  return function Wrapper({ children }: { children: ReactNode }) {
    return (
      <QueryClientProvider client={queryClient}>{children}</QueryClientProvider>
    );
  };
};

const mockConfig = {
  take_profit_enabled: true,
  take_profit_pct: 0.8,
  stop_loss_enabled: true,
  stop_loss_pct: -0.3,
  time_exit_enabled: true,
  time_exit_hours: 24,
  signal_exit_enabled: true,
  exit_check_interval_minutes: 5,
};

describe('ExitStrategySettings', () => {
  beforeEach(() => {
    vi.clearAllMocks();
  });

  describe('Loading State', () => {
    it('should show loading spinner while fetching config', async () => {
      vi.mocked(await import('@/api/settings')).settingsApi.getExitStrategy = vi
        .fn()
        .mockImplementation(() => new Promise(() => {})); // Never resolves

      const { ExitStrategySettings } = await import('./ExitStrategySettings');
      render(<ExitStrategySettings />, { wrapper: createWrapper() });

      expect(screen.getByText('加载中...')).toBeInTheDocument();
    });
  });

  describe('Success State', () => {
    it('should render all exit strategy toggles', async () => {
      vi.mocked(await import('@/api/settings')).settingsApi.getExitStrategy = vi
        .fn()
        .mockResolvedValue(mockConfig);

      const { ExitStrategySettings } = await import('./ExitStrategySettings');
      render(<ExitStrategySettings />, { wrapper: createWrapper() });

      await waitFor(() => {
        expect(screen.getByText('退出策略')).toBeInTheDocument();
      });

      expect(screen.getByText('止盈')).toBeInTheDocument();
      expect(screen.getByText('止损')).toBeInTheDocument();
      expect(screen.getByText('时间退出')).toBeInTheDocument();
      expect(screen.getByText('信号反转')).toBeInTheDocument();
    });

    it('should display current config values', async () => {
      vi.mocked(await import('@/api/settings')).settingsApi.getExitStrategy = vi
        .fn()
        .mockResolvedValue(mockConfig);

      const { ExitStrategySettings } = await import('./ExitStrategySettings');
      render(<ExitStrategySettings />, { wrapper: createWrapper() });

      await waitFor(() => {
        expect(screen.getByDisplayValue('80')).toBeInTheDocument(); // take_profit_pct * 100
      });
      expect(screen.getByDisplayValue('30')).toBeInTheDocument(); // stop_loss_pct * 100 (absolute)
      expect(screen.getByDisplayValue('24')).toBeInTheDocument(); // time_exit_hours
    });

    it('should have save button disabled when no changes', async () => {
      vi.mocked(await import('@/api/settings')).settingsApi.getExitStrategy = vi
        .fn()
        .mockResolvedValue(mockConfig);

      const { ExitStrategySettings } = await import('./ExitStrategySettings');
      render(<ExitStrategySettings />, { wrapper: createWrapper() });

      await waitFor(() => {
        expect(screen.getByRole('button', { name: /保存设置/i })).toBeDisabled();
      });
    });

    it('should enable save button when values change', async () => {
      const user = userEvent.setup();
      vi.mocked(await import('@/api/settings')).settingsApi.getExitStrategy = vi
        .fn()
        .mockResolvedValue(mockConfig);

      const { ExitStrategySettings } = await import('./ExitStrategySettings');
      render(<ExitStrategySettings />, { wrapper: createWrapper() });

      await waitFor(() => {
        expect(screen.getByText('退出策略')).toBeInTheDocument();
      });

      // Toggle take profit switch
      const switches = screen.getAllByRole('switch');
      await user.click(switches[0]);

      await waitFor(() => {
        expect(screen.getByRole('button', { name: /保存设置/i })).not.toBeDisabled();
      });
    });

    it('should call updateExitStrategy on save', async () => {
      const user = userEvent.setup();
      const mockUpdate = vi.fn().mockResolvedValue(mockConfig);

      vi.mocked(await import('@/api/settings')).settingsApi.getExitStrategy = vi
        .fn()
        .mockResolvedValue(mockConfig);
      vi.mocked(await import('@/api/settings')).settingsApi.updateExitStrategy = mockUpdate;

      const { ExitStrategySettings } = await import('./ExitStrategySettings');
      render(<ExitStrategySettings />, { wrapper: createWrapper() });

      await waitFor(() => {
        expect(screen.getByText('退出策略')).toBeInTheDocument();
      });

      // Toggle take profit switch to make change
      const switches = screen.getAllByRole('switch');
      await user.click(switches[0]);

      // Click save
      const saveButton = screen.getByRole('button', { name: /保存设置/i });
      await user.click(saveButton);

      await waitFor(() => {
        expect(mockUpdate).toHaveBeenCalledWith(
          expect.objectContaining({
            take_profit_enabled: false,
          })
        );
      });
    });

    it('should disable input when toggle is off', async () => {
      const user = userEvent.setup();
      const configWithDisabled = {
        ...mockConfig,
        take_profit_enabled: false,
      };

      vi.mocked(await import('@/api/settings')).settingsApi.getExitStrategy = vi
        .fn()
        .mockResolvedValue(configWithDisabled);

      const { ExitStrategySettings } = await import('./ExitStrategySettings');
      render(<ExitStrategySettings />, { wrapper: createWrapper() });

      await waitFor(() => {
        expect(screen.getByText('退出策略')).toBeInTheDocument();
      });

      // Find the take profit percentage input
      const inputs = screen.getAllByRole('spinbutton');
      const takeProfitInput = inputs[0];

      expect(takeProfitInput).toBeDisabled();
    });
  });
});

/**
 * Confirm Exit Dialog component tests.
 *
 * Tests for the ConfirmExitDialog component.
 *
 * Story 10.6: Dashboard 退出策略管理
 */

import { describe, it, expect, vi, beforeEach } from 'vitest';
import { render, screen } from '@testing-library/react';
import userEvent from '@testing-library/user-event';

// Mock the Dialog component
vi.mock('@/components/ui/dialog', () => ({
  Dialog: ({ children, open }: { children: React.ReactNode; open: boolean }) =>
    open ? <div data-testid="dialog">{children}</div> : null,
  DialogContent: ({ children }: { children: React.ReactNode }) => (
    <div data-testid="dialog-content">{children}</div>
  ),
  DialogHeader: ({ children }: { children: React.ReactNode }) => (
    <div data-testid="dialog-header">{children}</div>
  ),
  DialogTitle: ({ children }: { children: React.ReactNode }) => (
    <h2 data-testid="dialog-title">{children}</h2>
  ),
  DialogDescription: ({ children }: { children: React.ReactNode }) => (
    <p data-testid="dialog-description">{children}</p>
  ),
  DialogFooter: ({ children }: { children: React.ReactNode }) => (
    <div data-testid="dialog-footer">{children}</div>
  ),
}));

const mockPosition = {
  id: 1,
  market_id: 'test-market-123',
  outcome: 'YES' as const,
  shares: 100,
  avg_price: 0.5,
  cur_price: 0.6,
  current_value: 60,
  pnl: 10,
  status: 'open' as const,
  opened_at: '2024-01-15T10:00:00Z',
};

describe('ConfirmExitDialog', () => {
  beforeEach(() => {
    vi.clearAllMocks();
  });

  describe('when closed', () => {
    it('should not render when open is false', async () => {
      const { ConfirmExitDialog } = await import('./ConfirmExitDialog');
      render(
        <ConfirmExitDialog
          open={false}
          onOpenChange={vi.fn()}
          position={mockPosition}
          onConfirm={vi.fn()}
          isLoading={false}
        />
      );

      expect(screen.queryByTestId('dialog')).not.toBeInTheDocument();
    });
  });

  describe('when open', () => {
    it('should render dialog with position details', async () => {
      const { ConfirmExitDialog } = await import('./ConfirmExitDialog');
      render(
        <ConfirmExitDialog
          open={true}
          onOpenChange={vi.fn()}
          position={mockPosition}
          onConfirm={vi.fn()}
          isLoading={false}
        />
      );

      expect(screen.getByTestId('dialog')).toBeInTheDocument();
      expect(screen.getByText('确认退出持仓')).toBeInTheDocument();
      expect(screen.getByText('test-market-123')).toBeInTheDocument();
    });

    it('should display position outcome badge', async () => {
      const { ConfirmExitDialog } = await import('./ConfirmExitDialog');
      render(
        <ConfirmExitDialog
          open={true}
          onOpenChange={vi.fn()}
          position={mockPosition}
          onConfirm={vi.fn()}
          isLoading={false}
        />
      );

      expect(screen.getByText('YES')).toBeInTheDocument();
    });

    it('should display shares amount', async () => {
      const { ConfirmExitDialog } = await import('./ConfirmExitDialog');
      render(
        <ConfirmExitDialog
          open={true}
          onOpenChange={vi.fn()}
          position={mockPosition}
          onConfirm={vi.fn()}
          isLoading={false}
        />
      );

      expect(screen.getByText('100.00')).toBeInTheDocument();
    });

    it('should display average price', async () => {
      const { ConfirmExitDialog } = await import('./ConfirmExitDialog');
      render(
        <ConfirmExitDialog
          open={true}
          onOpenChange={vi.fn()}
          position={mockPosition}
          onConfirm={vi.fn()}
          isLoading={false}
        />
      );

      expect(screen.getByText('$0.5000')).toBeInTheDocument();
    });

    it('should display current value', async () => {
      const { ConfirmExitDialog } = await import('./ConfirmExitDialog');
      render(
        <ConfirmExitDialog
          open={true}
          onOpenChange={vi.fn()}
          position={mockPosition}
          onConfirm={vi.fn()}
          isLoading={false}
        />
      );

      expect(screen.getByText('$60.00')).toBeInTheDocument();
    });

    it('should display PnL with profit styling', async () => {
      const { ConfirmExitDialog } = await import('./ConfirmExitDialog');
      render(
        <ConfirmExitDialog
          open={true}
          onOpenChange={vi.fn()}
          position={mockPosition}
          onConfirm={vi.fn()}
          isLoading={false}
        />
      );

      expect(screen.getByText(/\+\$10.00/)).toBeInTheDocument();
    });

    it('should display PnL with loss styling for negative', async () => {
      const lossPosition = {
        ...mockPosition,
        pnl: -5,
        current_value: 45,
      };

      const { ConfirmExitDialog } = await import('./ConfirmExitDialog');
      render(
        <ConfirmExitDialog
          open={true}
          onOpenChange={vi.fn()}
          position={lossPosition}
          onConfirm={vi.fn()}
          isLoading={false}
        />
      );

      expect(screen.getByText(/-\$5.00/)).toBeInTheDocument();
    });

    it('should call onConfirm when confirm button clicked', async () => {
      const user = userEvent.setup();
      const mockOnConfirm = vi.fn();

      const { ConfirmExitDialog } = await import('./ConfirmExitDialog');
      render(
        <ConfirmExitDialog
          open={true}
          onOpenChange={vi.fn()}
          position={mockPosition}
          onConfirm={mockOnConfirm}
          isLoading={false}
        />
      );

      const confirmButton = screen.getByRole('button', { name: /确认退出/i });
      await user.click(confirmButton);

      expect(mockOnConfirm).toHaveBeenCalled();
    });

    it('should call onOpenChange(false) when cancel clicked', async () => {
      const user = userEvent.setup();
      const mockOnOpenChange = vi.fn();

      const { ConfirmExitDialog } = await import('./ConfirmExitDialog');
      render(
        <ConfirmExitDialog
          open={true}
          onOpenChange={mockOnOpenChange}
          position={mockPosition}
          onConfirm={vi.fn()}
          isLoading={false}
        />
      );

      const cancelButton = screen.getByRole('button', { name: /取消/i });
      await user.click(cancelButton);

      expect(mockOnOpenChange).toHaveBeenCalledWith(false);
    });

    it('should disable buttons when loading', async () => {
      const { ConfirmExitDialog } = await import('./ConfirmExitDialog');
      render(
        <ConfirmExitDialog
          open={true}
          onOpenChange={vi.fn()}
          position={mockPosition}
          onConfirm={vi.fn()}
          isLoading={true}
        />
      );

      const cancelButton = screen.getByRole('button', { name: /取消/i });
      const confirmButton = screen.getByRole('button', { name: /处理中/i });

      expect(cancelButton).toBeDisabled();
      expect(confirmButton).toBeDisabled();
    });

    it('should show loading state on confirm button', async () => {
      const { ConfirmExitDialog } = await import('./ConfirmExitDialog');
      render(
        <ConfirmExitDialog
          open={true}
          onOpenChange={vi.fn()}
          position={mockPosition}
          onConfirm={vi.fn()}
          isLoading={true}
        />
      );

      expect(screen.getByText('处理中...')).toBeInTheDocument();
    });

    it('should return null when position is null', async () => {
      const { ConfirmExitDialog } = await import('./ConfirmExitDialog');
      const { container } = render(
        <ConfirmExitDialog
          open={true}
          onOpenChange={vi.fn()}
          position={null}
          onConfirm={vi.fn()}
          isLoading={false}
        />
      );

      expect(container.innerHTML).toBe('');
    });
  });
});

