/**
 * Exit Strategy Settings component tests.
 *
 * Tests for the ExitStrategySettings component.
 *
 * Story 10.6: Dashboard 退出策略管理
 */

import { describe, it, expect, vi, beforeEach } from 'vitest';
import { render, screen, waitFor } from '@testing-library/react';
import userEvent from '@testing-library/user-event';
import { QueryClient, QueryClientProvider } from '@tanstack/react-query';
import type { ReactNode } from 'react';

// Mock the API
vi.mock('@/api/settings', () => ({
  settingsApi: {
    getExitStrategy: vi.fn(),
    updateExitStrategy: vi.fn(),
  },
}));

// Mock useToast
vi.mock('@/hooks/use-toast', () => ({
  useToast: () => ({
    toast: vi.fn(),
  }),
}));

const createWrapper = () => {
  const queryClient = new QueryClient({
    defaultOptions: {
      queries: {
        retry: false,
      },
    },
  });

  return function Wrapper({ children }: { children: ReactNode }) {
    return (
      <QueryClientProvider client={queryClient}>{children}</QueryClientProvider>
    );
  };
};

const mockConfig = {
  take_profit_enabled: true,
  take_profit_pct: 0.8,
  stop_loss_enabled: true,
  stop_loss_pct: -0.3,
  time_exit_enabled: true,
  time_exit_hours: 24,
  signal_exit_enabled: true,
  exit_check_interval_minutes: 5,
};

describe('ExitStrategySettings', () => {
  beforeEach(() => {
    vi.clearAllMocks();
  });

  describe('Loading State', () => {
    it('should show loading spinner while fetching config', async () => {
      vi.mocked(await import('@/api/settings')).settingsApi.getExitStrategy = vi
        .fn()
        .mockImplementation(() => new Promise(() => {})); // Never resolves

      const { ExitStrategySettings } = await import('./ExitStrategySettings');
      render(<ExitStrategySettings />, { wrapper: createWrapper() });

      expect(screen.getByText('加载中...')).toBeInTheDocument();
    });
  });

  describe('Success State', () => {
    it('should render all exit strategy toggles', async () => {
      vi.mocked(await import('@/api/settings')).settingsApi.getExitStrategy = vi
        .fn()
        .mockResolvedValue(mockConfig);

      const { ExitStrategySettings } = await import('./ExitStrategySettings');
      render(<ExitStrategySettings />, { wrapper: createWrapper() });

      await waitFor(() => {
        expect(screen.getByText('退出策略')).toBeInTheDocument();
      });

      expect(screen.getByText('止盈')).toBeInTheDocument();
      expect(screen.getByText('止损')).toBeInTheDocument();
      expect(screen.getByText('时间退出')).toBeInTheDocument();
      expect(screen.getByText('信号反转')).toBeInTheDocument();
    });

    it('should display current config values', async () => {
      vi.mocked(await import('@/api/settings')).settingsApi.getExitStrategy = vi
        .fn()
        .mockResolvedValue(mockConfig);

      const { ExitStrategySettings } = await import('./ExitStrategySettings');
      render(<ExitStrategySettings />, { wrapper: createWrapper() });

      await waitFor(() => {
        expect(screen.getByDisplayValue('80')).toBeInTheDocument(); // take_profit_pct * 100
      });
      expect(screen.getByDisplayValue('30')).toBeInTheDocument(); // stop_loss_pct * 100 (absolute)
      expect(screen.getByDisplayValue('24')).toBeInTheDocument(); // time_exit_hours
    });

    it('should have save button disabled when no changes', async () => {
      vi.mocked(await import('@/api/settings')).settingsApi.getExitStrategy = vi
        .fn()
        .mockResolvedValue(mockConfig);

      const { ExitStrategySettings } = await import('./ExitStrategySettings');
      render(<ExitStrategySettings />, { wrapper: createWrapper() });

      await waitFor(() => {
        expect(screen.getByRole('button', { name: /保存设置/i })).toBeDisabled();
      });
    });

    it('should enable save button when values change', async () => {
      const user = userEvent.setup();
      vi.mocked(await import('@/api/settings')).settingsApi.getExitStrategy = vi
        .fn()
        .mockResolvedValue(mockConfig);

      const { ExitStrategySettings } = await import('./ExitStrategySettings');
      render(<ExitStrategySettings />, { wrapper: createWrapper() });

      await waitFor(() => {
        expect(screen.getByText('退出策略')).toBeInTheDocument();
      });

      // Toggle take profit switch
      const switches = screen.getAllByRole('switch');
      await user.click(switches[0]);

      await waitFor(() => {
        expect(screen.getByRole('button', { name: /保存设置/i })).not.toBeDisabled();
      });
    });

    it('should call updateExitStrategy on save', async () => {
      const user = userEvent.setup();
      const mockUpdate = vi.fn().mockResolvedValue(mockConfig);

      vi.mocked(await import('@/api/settings')).settingsApi.getExitStrategy = vi
        .fn()
        .mockResolvedValue(mockConfig);
      vi.mocked(await import('@/api/settings')).settingsApi.updateExitStrategy = mockUpdate;

      const { ExitStrategySettings } = await import('./ExitStrategySettings');
      render(<ExitStrategySettings />, { wrapper: createWrapper() });

      await waitFor(() => {
        expect(screen.getByText('退出策略')).toBeInTheDocument();
      });

      // Toggle take profit switch to make change
      const switches = screen.getAllByRole('switch');
      await user.click(switches[0]);

      // Click save
      const saveButton = screen.getByRole('button', { name: /保存设置/i });
      await user.click(saveButton);

      await waitFor(() => {
        expect(mockUpdate).toHaveBeenCalledWith(
          expect.objectContaining({
            take_profit_enabled: false,
          })
        );
      });
    });

    it('should disable input when toggle is off', async () => {
      const user = userEvent.setup();
      const configWithDisabled = {
        ...mockConfig,
        take_profit_enabled: false,
      };

      vi.mocked(await import('@/api/settings')).settingsApi.getExitStrategy = vi
        .fn()
        .mockResolvedValue(configWithDisabled);

      const { ExitStrategySettings } = await import('./ExitStrategySettings');
      render(<ExitStrategySettings />, { wrapper: createWrapper() });

      await waitFor(() => {
        expect(screen.getByText('退出策略')).toBeInTheDocument();
      });

      // Find the take profit percentage input
      const inputs = screen.getAllByRole('spinbutton');
      const takeProfitInput = inputs[0];

      expect(takeProfitInput).toBeDisabled();
    });
  });
});

